<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><div><h2><?= esc($item->name) ?></h2><span class="badge bg-primary"><?= esc(ucfirst($item->status)) ?></span> <span class="text-muted">Revision <?= $item->revision ?></span></div><a class="btn btn-light" href="<?= base_url('school/admission/lotteries') ?>">Back</a></div>
<div class="row mb-3"><div class="col-md-3"><div class="card"><div class="card-body"><small>Seats</small><h3><?= $item->seat_count ?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Waiting</small><h3><?= $item->waiting_count ?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Candidates</small><h3><?= $item->candidate_count ?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Algorithm</small><div><?= esc($item->algorithm_version) ?></div></div></div></div></div>
<div class="card shadow-sm mb-3"><div class="card-body d-flex flex-wrap gap-2"><?php if($item->status==='draft'): ?><?= form_open('school/admission/lotteries/'.$item->token.'/lock') ?><button class="btn btn-warning" onclick="return confirm('Freeze the current eligible candidate list?')">Lock candidates</button></form><?php elseif($item->status==='locked'): ?><?= form_open('school/admission/lotteries/'.$item->token.'/run') ?><button class="btn btn-danger" onclick="return confirm('Run this lottery now? This action is one-time.')">Run secure draw</button></form><?php elseif($item->status==='drawn'): ?><?= form_open('school/admission/lotteries/'.$item->token.'/finalize') ?><button class="btn btn-success" onclick="return confirm('Finalize and publish this result?')">Finalize result</button></form><?php endif ?><?php if(in_array($item->status,['locked','drawn','finalized'],true)): ?><?= form_open('school/admission/lotteries/'.$item->token.'/cancel',['class'=>'d-flex gap-2']) ?><input class="form-control" name="reason" placeholder="Cancellation reason" required><button class="btn btn-outline-danger">Cancel lottery</button></form><?php endif ?></div></div>
<?php if($item->candidate_hash): ?><div class="alert <?= $audit['candidate_valid']&&$audit['result_valid']!==false?'alert-light':'alert-danger' ?>"><strong>Candidate snapshot:</strong> <code><?= esc($item->candidate_hash) ?></code> <span class="badge <?= $audit['candidate_valid']?'bg-success':'bg-danger' ?>"><?= $audit['candidate_valid']?'Verified':'Integrity failure' ?></span><?php if($item->result_hash): ?><br><strong>Result hash:</strong> <code><?= esc($item->result_hash) ?></code> <span class="badge <?= $audit['result_valid']?'bg-success':'bg-danger' ?>"><?= $audit['result_valid']?'Verified':'Integrity failure' ?></span><?php endif ?></div><?php endif ?>
<?php if($results): ?><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Position</th><th>Application</th><th>Applicant</th><th>Result</th><th>Waiting position</th></tr></thead><tbody><?php foreach($results as $r): ?><tr><td><?= $r->draw_position ?></td><td><?= esc($r->application_no) ?></td><td><?= esc($r->student_name) ?></td><td><?= esc(ucwords(str_replace('_',' ',$r->result))) ?></td><td><?= $r->waiting_position?:'—' ?></td></tr><?php endforeach ?></tbody></table></div></div><?php endif ?></div>
